#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PAGE = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doom responsiveness</title>
<style>
*{box-sizing:border-box}body{margin:0;background:transparent;color:var(--foreground,#20252b);font:14px/1.55 var(--font-sans,system-ui)}p{margin:0 0 14px}.lead{font-size:21px;font-weight:620;line-height:1.35;letter-spacing:-.3px}.muted,small{color:var(--muted-foreground,#64707c)}.note{font-size:12px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button{font:inherit;padding:8px 12px;border-radius:6px;border:1px solid var(--border,#ccd1d6);color:inherit;background:var(--card,#fff);cursor:pointer}button[aria-pressed=true]{background:var(--primary,#294956);color:var(--primary-foreground,#fff);border-color:transparent}button:focus-visible{outline:2px solid var(--ring,#4e8aa5);outline-offset:3px}.numbers{display:flex;gap:20px;margin:18px 0}.numbers>div{flex:1}.value{font-size:29px;line-height:1.2;font-weight:620;font-variant-numeric:tabular-nums}.caption{font-size:12px;margin-top:6px}.track{height:29px;display:flex;background:var(--muted,#e4e9ed);border-radius:5px;overflow:hidden;margin:14px 0}.history{background:var(--chart-1,#477f9e)}.assistant{background:var(--chart-2,#8a6ba3)}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px}.key{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:6px}.section{border-top:1px solid var(--border,#dce2e5);margin-top:23px;padding-top:18px}a{color:var(--primary,#2563eb);text-underline-offset:3px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:10px 6px;border-bottom:1px solid var(--border,#dce2e5);text-align:left}td:first-child,th:first-child{padding-left:0}th{font-weight:500;color:var(--muted-foreground,#64707c)}@media(max-width:480px){.lead{font-size:19px}.numbers{gap:12px}.value{font-size:25px}button{padding:7px 10px}}
</style>
<p class="lead">Doom can benefit from fresher frames after input.</p>
<p>The faster ViewFlipper result concerns images already inside the host. Doom still has to process a control, render its effect, and deliver new images. Its current native loop runs at 35 Hz; a 60 Hz flipper timer alone cannot create 60 new game states.</p>
<p class="muted note">Explore the frame-history tradeoff below. This is arithmetic from the current 33 ms sampler, not a measured touch-to-photon benchmark.</p>
<div class="controls" id="choices" role="group" aria-label="Frame deck strategy"></div>
<div aria-live="polite"><div class="numbers"><div><div class="value" id="age"></div><div class="caption muted">oldest frame at publication</div></div><div><div class="value" id="cadence"></div><div class="caption muted" id="cadenceLabel"></div></div></div>
<div class="track" role="img" id="track"><div class="history" id="history"></div><div class="assistant" style="width:25%"></div></div>
<div class="legend"><span><i class="key history"></i>Queued frame history</span><span><i class="key assistant"></i>200 ms assistant allowance</span></div>
<p class="note muted" style="margin-top:12px">Inflation and display time come afterward. This shows the first frame's age, not the time since a tap. The assistant allowance applies to the tested notification path.</p>
<p id="tradeoff"></p></div>
<div class="section"><p><strong>Two separate targets: freshness and reliable input.</strong> The existing isolated-tap path already discards older snapshots after a 60 ms settle interval. The shorter-deck candidate concerns repeated controls.</p>
<p class="note muted">Decorated custom notifications are marked for reinflation. An update can therefore replace a button during a press. More frequent publications may improve freshness while losing more taps. A control surface that does not update with the video is another experiment. <a href="https://android.googlesource.com/platform/frameworks/base/+/android-16.0.0_r1/core/java/android/app/Notification.java#8269">AOSP template construction</a></p></div>
<div class="section"><p><strong>A bitmap shortcut saved about 2 ms in an isolated test.</strong></p>
<table><thead><tr><th>Median transport + inflation</th><th>Trial 1</th><th>Trial 2</th></tr></thead><tbody><tr><td>Direct bitmap</td><td>0.66 ms</td><td>0.60 ms</td></tr><tr><td>BMP via memory-file URI</td><td>2.58 ms</td><td>2.45 ms</td></tr></tbody></table>
<p class="note muted" style="margin-top:12px">80 samples per mode per trial, separate provider process, identical 320×200 fixture. This excludes NotificationManager, SystemUI load, GPU presentation and touch latency. It does not demonstrate a gameplay improvement.</p></div>
<script>
const options=[{n:15,label:'15 frames · current',rate:'≈2/s',caption:'full-deck publications',text:'About 462 ms of frame history accumulates before delivery. Long idle decks preserve budget for a later isolated tap.'},{n:10,label:'10 frames · candidate',rate:'≈3/s',caption:'full-deck publications',text:'About 165 ms less frame history, with the same 33 ms playback request. This spends publication budget 50% faster and needs a real gameplay comparison for missed presses, frame age and rate shedding.'},{n:1,label:'Latest snapshot',rate:'Rate limited',caption:'distinct images follow accepted updates',text:'The queued history can be discarded, but fresh images then arrive only with permitted updates. It trades smooth motion for freshness; the flipper cannot play future game states that have not been rendered.'}];
function choose(index){const o=options[index],age=(o.n-1)*33;document.querySelectorAll('#choices button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));document.getElementById('age').textContent=age+' ms';document.getElementById('cadence').textContent=o.rate;document.getElementById('cadenceLabel').textContent=o.caption;document.getElementById('history').style.width=100*age/800+'%';document.getElementById('track').setAttribute('aria-label',age+' milliseconds of queued frame history plus a 200 millisecond assistant allowance, before inflation');document.getElementById('tradeoff').textContent=o.text}
options.forEach((o,i)=>{const b=document.createElement('button');b.type='button';b.textContent=o.label;b.onclick=()=>choose(i);document.getElementById('choices').appendChild(b)});choose(0);console.assert((15-10)*33===165);console.log(JSON.stringify({model:'frame age, not input latency',choices:options.length,productionDoomChanged:false}));
</script></html>'''
path = ROOT / 'artifacts/doom-optimization/explanation.html'
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(PAGE)
print(path)
